extra_css:
.theme-dragon-ball .card,.theme-dragon-ball .hero,.theme-dragon-ball .modal{border-width:2px;border-radius:1.25rem;box-shadow:0 0 0 1px rgba(255,208,0,.25),0 12px 30px rgba(255,122,0,.18);}
.theme-dragon-ball .hero{background:radial-gradient(circle at top right,#ffb300 0%,#ff7a00 25%,#5a2b00 55%,#1a0f00 100%);}
.theme-dragon-ball .primary{border-radius:999px;text-transform:uppercase;letter-spacing:.04em;box-shadow:0 6px 0 #b34700;}
.theme-dragon-ball .chip,.theme-dragon-ball .secondary,.theme-dragon-ball .text-input,.theme-dragon-ball .amount-input{border-radius:999px;}
.theme-dragon-ball .bottom-nav{border-top:2px solid #ff7a00;}
.theme-dragon-ball .tab.active{color:#ffd000;}
